map "https://fhir.labs.smartregister.org/fhir/StructureMap/b16b2831-9fe7-43c3-9440-8860b8ca9f79" = 'Remove Family'

uses "http://hl7.org/fhir/StructureDefinition/QuestionnaireResponse" as source
uses "http://hl7.org/fhir/StructureDefinition/Bundle" as target

group ecbisRemoveFamily(source questionnaireResponse : QuestionnaireResponse, target bundle: Bundle) {
    questionnaireResponse -> bundle.id = uuid() "rule_bundle_id";
    questionnaireResponse -> bundle.type = 'collection' "rule_bundle_type";
    questionnaireResponse then extractEncounter(questionnaireResponse, bundle) "rule_bundle_entry_ext_enc";
}

group extractEncounter(source questionnaireResponse: QuestionnaireResponse, target bundle: Bundle) {
    questionnaireResponse->bundle.entry as entry,
    entry.resource = create("Encounter") as encounter then {
        questionnaireResponse->encounter.id = uuid() "rule_enc_id";
        questionnaireResponse->encounter.status = "finished" "rule_enc_status";
        questionnaireResponse->encounter.class = c("http://terminology.hl7.org/CodeSystem/v3-ActCode", "HH","home health") "rule_enc_class";
        questionnaireResponse->encounter.serviceType = cc("http://terminology.hl7.org/CodeSystem/service-type", "85","Death Service Information") "rule_enc_ser_type";
        questionnaireResponse -> encounter.type = create('CodeableConcept') as concept then {
            questionnaireResponse -> concept.coding = c("https://smartregister.org/", "remove_family") as coding then {
                questionnaireResponse -> coding.display = "Remove family" "rule_display";
            } "rule_en_coding";
            questionnaireResponse -> concept.text = "Remove family" "rule_text";
        } "rule_en_type";
        questionnaireResponse -> encounter.priority = create('CodeableConcept') as priority then {
            questionnaireResponse -> priority.coding = c("http://terminology.hl7.org/ValueSet/v3-ActPriority", "EL") as priorityCoding then {
                questionnaireResponse -> priorityCoding.display = "Elective" "rule_en_cod_disp";
            } "rule_en_cc_cod";
            questionnaireResponse -> priority.text = "Elective" "rule_en_prio_text";
        } "rule_priority";
        questionnaireResponse -> encounter.subject = create('Reference') as ref then {
            questionnaireResponse-> ref.reference = evaluate(questionnaireResponse, 'Patient/' + $this.item.where(linkId = "261fdbe6-e0aa-48e5-824b-55314b60d8d6").answer.value) "rule_item_observation_reference";
        } "rule_observation_reference";
        questionnaireResponse -> encounter.period = create('Period') as period then {
            questionnaireResponse -> period.start = evaluate(questionnaireResponse, now()) "rule_period_start";
            questionnaireResponse -> period.end = evaluate(questionnaireResponse, now()) "rule_period_end";
        } "rule_period";
        questionnaireResponse -> encounter.reasonCode = create('CodeableConcept') as reason then {
            questionnaireResponse -> reason.text = "Remove family" "rule_en_text";
            questionnaireResponse -> reason.coding = c("https://smartregister.org/", "remove_family") "rule_rea_cd";
        } "rule_en_reason";

        questionnaireResponse then extractReasonForRemoval(questionnaireResponse, bundle, encounter) "rule_enc_ext_observation";
        questionnaireResponse then setHouseholdActiveAsFalseAndDelete(questionnaireResponse, bundle) "rule_enc_set_household_active_as_false";
    } "rule_bundle_entry_enc";
}

group extractReasonForRemoval(source questionnaireResponse: QuestionnaireResponse, target bundle: Bundle, target encounter: Encounter) {
    questionnaireResponse.item as questionnaireItem where(linkId = "c072659f-33a1-4ca3-86bb-073afad8290e") then {
        questionnaireResponse->bundle.entry as entry, entry.resource = create("Observation") as observation then {
            questionnaireResponse -> observation.code = cc("https://smartregister.org/", "remove-group-reason", "Family Removal Reason") "rule_item_removal_reason_observation_code";
            questionnaireResponse -> observation.value = create("CodeableConcept")as codeableConcept then {
                questionnaireResponse -> codeableConcept.coding = evaluate(questionnaireItem, $this.answer.value.code) "rule_item_removal_reason_observation_value_cc_coding";
                questionnaireResponse -> codeableConcept.text = evaluate(questionnaireResponse, $this.answer.value.display) "rule_item_removal_reason_observation_cc_display";
            } "rule_item_removal_reason_observation_value";

            questionnaireResponse then extractObservations(questionnaireResponse, bundle, encounter, observation) "rule_item_observation_exttraction";

            questionnaireItem where(answer.value.code = 'moved-away') then extractMoveAwayDate(questionnaireResponse, bundle, encounter) "rule_item_extract_remove_date";
            questionnaireItem where(answer.value.code = 'died') then extractDeathDate(questionnaireResponse, bundle, encounter) "rule_item_extract_death_date";
            questionnaireItem where(answer.value.code = 'other') then extractOtherIndicateReason(questionnaireResponse, bundle, encounter) "rule_item_extract_other_reason_indicate";
        } "rule_observation";
    } "rule_item_removal_reason";
}

group extractMoveAwayDate(source questionnaireResponse: QuestionnaireResponse, target bundle: Bundle, target encounter: Encounter) {
    questionnaireResponse.item as questionnaireItem where(linkId = "859f0b8e-80b6-4a15-f6a5-b1bec78d928c") then {
        questionnaireResponse->bundle.entry as entry, entry.resource = create("Observation") as observation then {
            questionnaireResponse -> observation.code = cc("https://smartregister.org/", "removal-reason-date", "Family Removal Date") "rule_item_date_reason_moved_away_observation_code";
            questionnaireResponse -> observation.value = evaluate(questionnaireItem, $this.answer.value.toString() + 'T00:00:00.00Z') "rule_item_reason_moved_away_date_observation_value";

            questionnaireResponse then extractObservations(questionnaireResponse, bundle, encounter, observation) "rule_item_observation_exttraction";
        } "rule_observation";
    } "rule_item_reason_moved_away";
}

group extractDeathDate(source questionnaireResponse: QuestionnaireResponse, target bundle: Bundle, target encounter: Encounter) {
    questionnaireResponse.item as questionnaireItem where(linkId = "4c495cf6-4ffa-4b14-8998-5f51bd00bce5") then {
        questionnaireResponse->bundle.entry as entry, entry.resource = create("Observation") as observation then {
            questionnaireResponse -> observation.code = cc("https://smartregister.org/", "removal-reason-date", "Family Removal Date") "rule_item_date_reason_moved_away_observation_code";
            questionnaireResponse -> observation.value = evaluate(questionnaireItem, $this.answer.value.toString() + 'T00:00:00.00Z') "rule_item_reason_moved_away_date_observation_value";

            questionnaireResponse then extractObservations(questionnaireResponse, bundle, encounter, observation) "rule_item_observation_exttraction";
        } "rule_observation";
    } "rule_item_reason_moved_away";
}

group extractOtherIndicateReason(source questionnaireResponse: QuestionnaireResponse, target bundle: Bundle, target encounter: Encounter) {
    questionnaireResponse.item as questionnaireItem where(linkId = "b6a432a9-7026-4543-9f56-fc404e1d42c6") then {
        questionnaireResponse->bundle.entry as entry, entry.resource = create("Observation") as observation then {
            questionnaireResponse -> observation.value = create("CodeableConcept")as codeableConcept then {
                questionnaireResponse -> observation.code = cc("https://smartregister.org/", "group_other-remove-reason", "Other Family Removal Reason") "rule_item_other_indicate_reason_observation_code";
                questionnaireResponse -> codeableConcept.coding = evaluate(questionnaireItem, $this.answer.value.code) "rule_item_other_indicate_reason_observation_value_cc_coding";
                questionnaireResponse -> codeableConcept.text = 'Removal other reason' "rule_item_other_indicate_reason_observation_cc_display";
            } "rule_item_other_indicate_reason_observation_value";
            questionnaireResponse then extractObservations(questionnaireResponse, bundle, encounter, observation) "rule_item_observation_exttraction";
        } "rule_observation";
    } "rule_item_other_indicate_reason";
}

group extractObservations(source questionnaireResponse: QuestionnaireResponse, target bundle: Bundle, target encounter: Encounter,  target observation: Observation) {
    questionnaireResponse->observation.id = uuid() "rule_observation_id";
    questionnaireResponse->observation.subject = create("Reference")as ref then {
        questionnaireResponse->ref.reference = evaluate(questionnaireResponse, 'Patient/' + $this.item.where(linkId = "261fdbe6-e0aa-48e5-824b-55314b60d8d6").answer.value) "rule_item_observation_reference";
    } "rule_observation_reference";
    questionnaireResponse->observation.encounter = reference(encounter) "rule_observation_encounter";
    questionnaireResponse->observation.category = cc("http://terminology.hl7.org/CodeSystem/observationervation-category", "social-history", "Social History") "rule_observation_catergory";
    questionnaireResponse->observation.effective = evaluate(questionnaireResponse, now()) "rule_observation_effective";
    questionnaireResponse -> observation.status = "final" "rule_item_removal_reason_observation_status";
}

group setHouseholdActiveAsFalseAndDelete(source questionnaireResponse: QuestionnaireResponse, target bundle: Bundle) {
    questionnaireResponse.item as questionnaireItem where(linkId = "261fdbe6-e0aa-48e5-824b-55314b60d8d6") then {
        questionnaireResponse->bundle.entry as entry, entry.resource = create("Group") as household then {
            questionnaireResponse->household.id = create("id") as household_id then {
                questionnaireResponse->household_id.value = evaluate(questionnaireItem, $this.answer.value) "rule_item_group_set_pat_id";
            } "rule_item_group_create_pat_id";
            questionnaireResponse -> household.active = false "rule_item_group_active";
            questionnaireResponse -> household.characteristic = create('Group_Characteristic') as excludeFamily then {
                questionnaireResponse -> excludeFamily.exclude = true "rule_exclude_group_true";
            } "rule_group_char";
            questionnaireResponse -> household.characteristic = create('Group_Characteristic') as familyCharacteristic then {
                questionnaireResponse -> familyCharacteristic.code = create('CodeableConcept') as familyCharacteristicCode then{
                    questionnaireResponse -> familyCharacteristicCode.coding = c("https://smartregister.org/", "inactive") as coding then {
                       questionnaireResponse -> coding.display = 'inactive' "rule_cod_disp";
                    } "rule_grp_vcode";
               } "rule_group_char_code";
            } "rule_group_char";
        } "rule_item_group";
    } "rule_item_group_id";
}